with incoming(lemma, kind, sense_id, ordinal, pos, gender, text, example, example_translation) as (values ('komme over', 'phrase', 'a4cf9f7c-42bd-58d8-9451-cfddc677d2a5', 1, 'verb', null, 'to come over (to visit)', 'Vil du komme over til mig i aften?', 'Will you come over to my place tonight?'), ('komme over', 'phrase', 'd4a372bb-97b6-5da7-b937-3fe9bafad910', 2, 'verb', null, 'to get over (a difficulty)', 'Hun kom over sin frygt for hunde.', 'She got over her fear of dogs.'), ('gå under', 'phrase', 'c4d82663-1ab7-53c8-9231-1da8b7f06319', 1, 'verb', null, 'to sink (of a ship)', 'Det gamle skib gik under i stormen.', 'The old ship sank in the storm.'), ('gå under', 'phrase', 'a8de78fc-f7ea-57fa-95de-a648a293ce36', 2, 'verb', null, 'to perish (of a civilisation, company)', 'Mange små butikker går under i krisen.', 'Many small shops are going under in the crisis.'), ('dele sig', 'phrase', '84f2c3e9-b949-56c2-a8a4-47c6eab03672', 1, 'verb', null, 'to split (into parts)', 'Floden deler sig i to grene lige efter broen.', 'The river splits into two branches just after the bridge.'), ('dele sig', 'phrase', '347ad1c2-eb0d-56e8-9ece-00e1b6b4aa02', 2, 'verb', null, 'to fork (of a road or group)', 'Stien deler sig, så vi må vælge en vej.', 'The path forks, so we have to choose a way.'), ('holde for', 'phrase', '12f65054-ad15-5e09-821b-c605b6e2c51e', 1, 'verb', null, 'to cover (one''s nose, ears, eyes) with one''s hand', 'Jeg holder for ørerne, når toget kører forbi.', 'I cover my ears when the train passes by.'), ('ligge over', 'phrase', '117cab92-b318-59fc-8933-5df8fbcb1f0f', 1, 'verb', null, 'to stay overnight', 'Jeg ligger over hos min veninde i weekenden.', 'I''m staying over at my friend''s place this weekend.'), ('blive tilbage', 'phrase', '1666bbdb-5e91-5cf0-b3d7-233ff2a4671b', 1, 'verb', null, 'to stay behind', 'Hun bliver tilbage på kontoret, når de andre går hjem.', 'She stays behind in the office when the others go home.'), ('holde sig tilbage', 'phrase', '7634fcde-aed3-52f7-9875-08894384223f', 1, 'verb', null, 'to hold back', 'Jeg holdt mig tilbage, selvom jeg var vred.', 'I held back, even though I was angry.'), ('spille med', 'phrase', '2cebd4f5-4d3d-517a-91b3-ce99a556fa4e', 1, 'verb', null, 'to play along (agree to someone''s plan)', 'Han spiller med på ideen om en tur til stranden.', 'He plays along with the idea of a trip to the beach.'), ('køre ind i', 'phrase', '14cdea87-6993-5bae-bfcc-0f2347d38fa9', 1, 'verb', null, 'to crash into', 'Bilen kørte ind i et træ.', 'The car crashed into a tree.'), ('slå i', 'phrase', 'b7218141-5770-5700-b5dc-d9e363b310fe', 1, 'verb', null, 'to hit (something)', 'Han slog i bordet af vrede.', 'He banged the table in anger.'), ('slå sig på', 'phrase', 'fbec78cc-0dd0-5109-9066-79b1190f2d3e', 1, 'verb', null, 'to hurt (oneself)', 'Jeg slog mig på knæet, da jeg faldt.', 'I hurt my knee when I fell.'), ('møde op', 'phrase', '35400702-7646-55ff-acf5-bbd02edc8fd0', 1, 'verb', null, 'to show up', 'Hun mødte op til mødet uden sin computer.', 'She showed up for the meeting without her computer.'), ('handle med', 'phrase', '77588a85-6ece-52f0-b6ec-3531f5694fdc', 1, 'verb', null, 'to trade in (something)', 'De handler med frugt og grøntsager på torvet.', 'They trade in fruit and vegetables in the square.'), ('stige af', 'phrase', '52dfa294-4641-596f-9289-b508481e2821', 1, 'verb', null, 'to get off (a vehicle)', 'Jeg stiger af bussen ved stationen.', 'I get off the bus at the station.'), ('have lov til', 'phrase', '9dec08c9-ed2a-527e-b710-49139b15706a', 1, 'verb', null, 'to be allowed to', 'Børnene har lov til at lege i haven.', 'Children are allowed to play in the garden.'), ('vente med', 'phrase', 'ed35c79d-4e8f-57c7-bf5c-9c4ffbcd4240', 1, 'verb', null, 'to postpone (something)', 'Vi venter med mødet til i morgen.', 'We are postponing the meeting until tomorrow.'), ('stille op', 'phrase', '6c73dcf5-be9f-5a51-87c4-0a819a3eda80', 1, 'verb', null, 'to stand as a candidate (in an election)', 'Hun stiller op til kommunalvalget næste år.', 'She is running in the municipal elections next year.'), ('stille op', 'phrase', 'b410c00e-c092-5787-be25-d7f765f5919b', 2, 'verb', null, 'to line up (people or things)', 'Læreren bad børnene stille op på to rækker.', 'The teacher asked the children to line up in two rows.'), ('bag ved', 'phrase', 'b9296121-df4e-5c6c-8e0d-c74e1a2a2f47', 1, 'preposition', null, 'behind', 'Huset ligger lige bag ved skolen.', 'The house is located right behind the school.'), ('hjælpe på', 'phrase', 'b87e8502-a18a-531b-bf0a-e9840f9ba42d', 1, 'verb', null, 'to improve (a situation)', 'Det hjælper på humøret at gå en tur.', 'Going for a walk helps your mood.'), ('flytte sig', 'phrase', 'bd7988d3-059a-567c-8f6c-46429e9938a8', 1, 'verb', null, 'to move (oneself)', 'Kan du flytte dig lidt til siden?', 'Can you move a little to the side?'), ('flytte ud', 'phrase', '09fbbe18-ca96-53eb-963d-25e5bd9cf413', 1, 'verb', null, 'to move out (of a home)', 'Min nabo flyttede ud i sidste uge.', 'My neighbour moved out last week.'), ('rette på', 'phrase', '3a5829c2-8b70-5940-bdeb-10a8f8162728', 1, 'verb', null, 'to adjust (clothing, hair)', 'Hun retter på slipset før mødet.', 'She straightens her tie before the meeting.'), ('blive væk', 'phrase', '42e42e7f-ca94-508e-8429-fa2cd9751137', 1, 'verb', null, 'to go missing, to get lost', 'Min nøgle bliver væk hele tiden.', 'My key gets lost all the time.'), ('være igennem', 'phrase', '6bd6fd58-3452-5d68-84a0-9c505008cc62', 1, 'verb', null, 'to go through (something)', 'Hun er igennem en svær periode lige nu.', 'She is going through a difficult period right now.'), ('lave numre', 'phrase', '8bd4fd3f-3bfe-5655-8307-ed2407b153ee', 1, 'verb', null, 'to make a scene, to act up', 'Børnene laver numre, når de er trætte.', 'The children act up when they are tired.'), ('hen ad', 'phrase', '74f8f698-59de-5fca-b651-bc3eb491e09b', 1, 'preposition', null, 'along, towards', 'De gik hen ad vejen i stilhed.', 'They walked along the road in silence.'), ('løbe af med', 'phrase', 'a4b72c87-82c8-5998-a035-32266643a379', 1, 'verb', null, 'to run off with (something)', 'Tyven løb af med min taske.', 'The thief ran away with my bag.'), ('løbe af med', 'phrase', 'ac66a13b-caac-592f-b1df-2059f22c3cc3', 2, 'verb', null, 'to win (easily)', 'Hun løb af med førstepræmien.', 'She easily won the first prize.'), ('håbe på', 'phrase', '8208e60d-67f3-5933-8a77-3c2cbf11eb05', 1, 'verb', null, 'to hope for', 'Jeg håber på godt vejr i morgen.', 'I hope for good weather tomorrow.'), ('tage en beslutning', 'phrase', '672dc7a2-2e01-58ae-a05f-ce9350745dbd', 1, 'verb', null, 'to make a decision', 'Hun tager en beslutning om sit nye job i morgen.', 'She will make a decision about her new job tomorrow.'), ('komme i tvivl', 'phrase', '73f6b0eb-d1ef-5a50-8a75-0b6ad5986a95', 1, 'verb', null, 'to start doubting', 'Jeg kom i tvivl om svaret var rigtigt.', 'I started doubting whether the answer was correct.'), ('være foran', 'phrase', '4327e985-37a7-5817-962a-2267eed915ae', 1, 'verb', null, 'to be ahead', 'Vores hold er foran med to mål.', 'Our team is ahead by two goals.'), ('stemme i', 'phrase', '48cebe76-437d-5f81-a0ec-d59d532b9b04', 1, 'verb', null, 'to join in singing', 'Alle børnene stemte i på omkvædet.', 'All the children joined in singing the chorus.'), ('skifte til', 'phrase', '8a0a1b49-cebe-5c51-8526-0be78de2cfb1', 1, 'verb', null, 'to switch to', 'Jeg skifter til en anden kanal.', 'I''m switching to a different channel.'), ('sidde inde', 'phrase', '8cbebd22-a90a-57e2-943d-a76e6aebc1a1', 1, 'verb', null, 'to be in prison', 'Han sad inde i to år for tyveri.', 'He was imprisoned for two years for theft.'), ('sidde inde', 'phrase', 'df3dc8dc-99a7-52f7-970e-85a50a18d1f0', 2, 'verb', null, 'to possess (knowledge)', 'Hun sidder inde med vigtig viden om sagen.', 'She has important knowledge about the case.'), ('stå inde for', 'phrase', '315e5f1f-c533-5783-bde3-a0817f8b59fe', 1, 'verb', null, 'to vouch for', 'Jeg står inde for kvaliteten af vores produkter.', 'I vouch for the quality of our products.'), ('være inde', 'phrase', 'c5c834a5-8b15-5902-9031-5afe70414d06', 1, 'verb', null, 'to be inside (a building)', 'Jeg er inde i stuen og læser en bog.', 'I''m inside in the living room reading a book.'), ('melde sig til', 'phrase', 'e9e9eadd-32a3-59ab-ba84-cd6f8934f5f0', 1, 'verb', null, 'to sign up (for a course, event)', 'Jeg melder mig til et kursus i næste uge.', 'I''m signing up for a course next week.'), ('gå fra borde', 'phrase', '2b6c0860-9b26-5e05-840b-02e36eaa1e3f', 1, 'verb', null, 'to disembark (from a ship)', 'Passagererne gik fra borde i København.', 'The passengers disembarked in Copenhagen.'), ('slippe af med', 'phrase', '7cb01bcd-f057-53dd-96c3-2684ae8a3f82', 1, 'verb', null, 'to get rid of', 'Jeg slap af med min gamle sofa i går.', 'I got rid of my old couch yesterday.'), ('synge med', 'phrase', '0d9c0305-ee61-58bd-ad3f-076d9bfd9627', 1, 'verb', null, 'to sing along', 'Hun synger med på sangen i radioen.', 'She sings along to the song on the radio.'), ('tanke op', 'phrase', '8088c4e1-7e8e-53a5-b693-43ecb38e6f1b', 1, 'verb', null, 'to refuel', 'Vi tanker op inden den lange tur.', 'We refuel before the long trip.'), ('skære sig', 'phrase', '75b4479a-c452-5380-983a-c5157dd9a24b', 1, 'verb', null, 'to cut oneself', 'Jeg skar mig på kniven i går.', 'I cut myself on the knife yesterday.'), ('skifte emne', 'phrase', '4f771aed-2bd0-5f70-9f44-5d9751138041', 1, 'verb', null, 'to change the subject', 'Vi skifter emne, fordi det er for pinligt.', 'We change the subject because it is too embarrassing.'), ('styre sig', 'phrase', '70f12b32-bd63-5cd0-a503-ceeefb9c2e65', 1, 'verb', null, 'to control oneself', 'Du må styre dig, selvom du er vred.', 'You have to control yourself, even if you are angry.'), ('snakke sammen', 'phrase', '6dff755f-b23f-5fc6-8d15-9a3997f15d44', 1, 'verb', null, 'to talk (to each other)', 'Vi snakker sammen hver aften.', 'We talk to each other every evening.'), ('fejre jul', 'phrase', 'd9479a0d-2258-5e06-891a-6c87be1c0d55', 1, 'verb', null, 'to celebrate Christmas', 'Vi fejrer jul hos mine forældre i år.', 'We are celebrating Christmas at my parents'' place this year.'), ('fred og ro', 'phrase', '19ea8ca8-f400-5104-9c4c-03b593245d7d', 1, 'phrase', null, 'peace and quiet', 'Jeg har brug for fred og ro efter arbejde.', 'I need peace and quiet after work.'), ('tage på ferie', 'phrase', '82d4fb2c-ef98-5bef-9735-d78a132dfc0b', 1, 'verb', null, 'to go on holiday (vacation)', 'Vi tager på ferie til Italien hver sommer.', 'We go on holiday to Italy every summer.'), ('springe ind', 'phrase', '18371915-8d67-5cb4-90fb-c876602d6205', 1, 'verb', null, 'to step in (as a substitute)', 'Hun sprang ind for den syge lærer i går.', 'She stepped in for the sick teacher yesterday.'), ('finde sig i', 'phrase', '9e2de5e6-2850-5349-9138-81c5f07ba07f', 1, 'verb', null, 'to put up with, to tolerate', 'Hun finder sig i meget fra sin chef.', 'She puts up with a lot from her boss.')),
known as (
  select incoming.* from incoming
  where exists (
    select 1 from public.word_catalog_sense existing
    where existing.lemma = incoming.lemma and existing.kind = incoming.kind
      and existing.sense_id = incoming.sense_id::uuid and existing.lang <> 'en'
  )
),
written as (
  insert into public.word_catalog_sense (lemma, kind, sense_id, ordinal, lang, text, pos, gender, example, example_translation, generator)
  select lemma, kind, sense_id::uuid, ordinal, 'en', text, pos, gender, example, example_translation, 'pipeline-phrases-0007' from known
  on conflict (lemma, kind, sense_id, lang) do update set
    text = excluded.text, example = excluded.example, example_translation = excluded.example_translation, generator = excluded.generator
  returning 1
)
select (select count(*) from incoming) as incoming, (select count(*) from known) as matched, (select count(*) from written) as written;
